import{z as A,x as B,o as t,c as p,q as r,j as o,D as E,d as n,s as l,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"无约束一阶与二阶条件","description":"","frontmatter":{"title":"无约束一阶与二阶条件","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/unconstrained-fonc.md","filePath":"econ/unconstrained-fonc.md","lastUpdated":1791413859000}'),d={name:"econ/unconstrained-fonc.md"};function f(C,a,h,m,x,c){const i=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="无约束一阶与二阶条件" tabindex="-1">无约束一阶与二阶条件 <a class="header-anchor" href="#无约束一阶与二阶条件" aria-label="Permalink to &quot;无约束一阶与二阶条件&quot;">​</a></h1><div class="epigraph"><p>内点最优处梯度必须为零；凹目标让这句话从必要变成充分。</p><footer>—— 据 Mas-Colell, Whinston and Green 数学附录；Boyd and Vandenberghe, Convex Optimization, 第 4 章整理</footer></div><p>上一课<a href="/econ/separating-hyperplane">分离超平面</a>用平面把凸集切开。无约束光滑问题更短：可行域是开集，没有边界可支撑，唯一能站住的一阶陈述是「没有方向还能改善」。缺口是把这句写成梯度与 Hessian。约束、乘子、KKT 是后两课；本课先把无约束钉死，以免后课把 \\(\\nabla\\mathcal{L}=0\\) 里的 \\(\\nabla u=0\\) 与乘子项混在一起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(f\\) 在开集 \\(U\\subset\\mathbb{R}^n\\) 上可微，\\(x^*\\in U\\) 为局部极大（或极小）。沿任何方向 \\(v\\) 的方向导数必须为零，否则朝 \\(v\\) 或 \\(-v\\) 可改善。故<strong>一阶必要条件</strong>（FONC）：\\(\\nabla f(x^*)=0\\)。二阶：Hessian \\(H=\\nabla^2 f(x^*)\\) 在极大处半负定，在极小处半正定。严格负定给出严格局部极大的充分条件（加上梯度为零）。</p><p>经济学里无约束不是「没有预算」，而是「约束暂时不发言」：内部解、或已把约束代入消元之后。厂商在 \\(\\mathbb{R}^n\\) 上选投入、利润已写成无约束函数时，FONC 就是要素的边际产值等于价格那一组方程。角点、不等式留给 KKT。</p><h3 id="驻点不是最优" tabindex="-1">驻点不是最优 <a class="header-anchor" href="#驻点不是最优" aria-label="Permalink to &quot;驻点不是最优&quot;">​</a></h3><p>梯度为零只说一阶没有方向。鞍点、极小、极大都是驻点。\\(f(x,y)=x^2-y^2\\) 在原点梯度为零，沿 \\(x\\) 极小沿 \\(y\\) 极大。二阶不定时，一阶条件帮倒忙。凹目标（极大化）或凸目标（极小化）把全体驻点变成全局最优：上一课的弦不等式让一阶下估变成全局比较。没有凹/凸，FONC 连局部充分都谈不上，更不要说全局。</p><p><span class="marginnote">\\(C^1\\) 足够写 FONC；\\(C^2\\) 才写 Hessian。比较静态后课常直接假设 \\(C^2\\)，为的是对隐函数求导，不是因为最优存在需要二阶。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>必要与充分要分开记。必要：局部内点最优 \\(\\Rightarrow\\) 梯度零、Hessian 半定（若 \\(C^2\\)）。充分：梯度零 + Hessian 负定 \\(\\Rightarrow\\) 严格局部极大。全局充分：在凸开集上 \\(f\\) 凹且 \\(\\nabla f(x^*)=0\\) \\(\\Rightarrow\\) \\(x^*\\) 为全局极大。后课多数消费者、规划者问题走最后这条，不靠逐点检查特征值。</p><p>边界点不服从无约束 FONC。若 \\(x^*\\) 在 \\(U\\) 的闭包但不在 \\(U\\) 内，方向导数只对可行方向为零。那是约束问题。把非负约束忽略、直接令 \\(\\nabla f=0\\)，可能解出负消费——这是后课<a href="/econ/interior-corner">内点与角点</a>要拦的错误，本课先标明适用范围：内点。</p>',12)),(t(),o(s,null,{default:E(()=>[l(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20INT%5B%22%E5%BC%80%E9%9B%86%E5%86%85%E7%82%B9%E6%9C%80%E4%BC%98%22%5D%20--%3E%20G%5B%22%E6%A2%AF%E5%BA%A6%E4%B8%BA%E9%9B%B6%22%5D%0A%20%20G%20--%3E%20H%5B%22Hessian%20%E5%8D%8A%E8%B4%9F%E5%AE%9A%EF%BC%9A%E5%BF%85%E8%A6%81%22%5D%0A%20%20G%20--%3E%20S%5B%22Hessian%20%E8%B4%9F%E5%AE%9A%EF%BC%9A%E5%B1%80%E9%83%A8%E5%85%85%E5%88%86%22%5D%0A%20%20CCV%5B%22%E5%87%B9%E7%9B%AE%E6%A0%87%22%5D%20--%3E%20GLB%5B%22%E9%A9%BB%E7%82%B9%E5%8D%B3%E5%85%A8%E5%B1%80%E6%9E%81%E5%A4%A7%22%5D%0A%20%20GLB%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%8A%A0%E4%B8%8A%E7%AD%89%E5%BC%8F%E7%BA%A6%E6%9D%9F%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"泰勒展开 \\(f(x^*+tv)=f(x^*)+t\\nabla f^\\top v+\\frac{t^2}{2}v^\\top H v+o(t^2)\\)。\\(t\\) 任意小时，线性项必须消失，否则选 \\(t\\) 的符号就能升。线性项消失后，二次项决定弯曲：负定则附近都更低。凹函数的一阶上估 \\(f(y)\\le f(x)+\\nabla f(x)^\\top(y-x)\\) 在 \\(\\nabla f(x)=0\\) 时直接给出 \\(f(y)\\le f(x)\\)，不需要 \\(t\\) 小——这是全局化的一步。",-1)),a[5]||(a[5]=e("p",null,"多变量时交叉偏导进入 Hessian。Young 定理（\\(C^2\\)）让混合偏导对称，后课斯勒茨基对称与此同源，但斯勒茨基还有支出最小化的结构，不要在本课提前写需求。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},[n("一阶条件是 \\(n\\) 个方程对 \\(n\\) 个未知数。解的局部唯一靠 Hessian 非奇异，那是"),e("a",{href:"/econ/implicit-function"},"隐函数定理"),n("的输入，本课只准备矩阵。")])],-1)),(t(),o(s,null,{default:E(()=>[l(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20LR%0A%20%20P%5B%22%E5%9C%A8%20x*%20%2B%20tv%20%E5%A4%84%E5%B1%95%E5%BC%80%22%5D%20--%3E%20L%5B%22%E7%BA%BF%E6%80%A7%E9%A1%B9%20t%C2%B7%E2%88%87f%C2%B7v%22%5D%0A%20%20L%20--%20%22%E2%88%87f%20%E2%89%A0%200%22%20--%3E%20ESC%5B%22%E6%8C%91%20t%20%E7%9A%84%E7%AC%A6%E5%8F%B7%E7%AB%8B%E5%88%BB%E8%83%BD%E6%94%B9%E5%96%84%EF%BC%9Ax*%20%E4%B8%8D%E6%98%AF%E6%9C%80%E4%BC%98%22%5D%0A%20%20L%20--%20%22%E2%88%87f%20%3D%200%22%20--%3E%20Q%5B%22%E5%8F%AA%E5%89%A9%E4%BA%8C%E6%AC%A1%E9%A1%B9%EF%BC%9At%C2%B2%2F2%20%C2%B7%20v'Hv%22%5D%0A%20%20Q%20--%20%22H%20%E8%B4%9F%E5%AE%9A%22%20--%3E%20MAX%5B%22%E9%99%84%E8%BF%91%E5%85%A8%E6%9B%B4%E4%BD%8E%EF%BC%9A%E5%B1%80%E9%83%A8%E6%9E%81%E5%A4%A7%22%5D%0A%20%20Q%20--%20%22H%20%E4%B8%8D%E5%AE%9A%22%20--%3E%20SAD%5B%22%E6%9C%89%E7%9A%84%E6%96%B9%E5%90%91%E5%8D%87%E6%9C%89%E7%9A%84%E9%99%8D%EF%BC%9A%E9%9E%8D%E7%82%B9%22%5D%0A%20%20Q%20--%20%22H%20%E6%AD%A3%E5%AE%9A%22%20--%3E%20MIN%5B%22%E5%B1%80%E9%83%A8%E6%9E%81%E5%B0%8F%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">「梯度」可以翻译成坡度向量：把多元函数想成一座山，你在某点感受到的最陡上坡方向和坡度合起来就是梯度。梯度为零 = 站在四面八方都不上不下的位置——可能是山顶、谷底，也可能是马鞍中心，光凭坡度分不清。</span></p><p><span class="marginnote">数字实例：\\(f(x,y)=x^2-y^2\\) 在原点两个偏导都是零，但沿 \\(x\\) 轴走是上坡、沿 \\(y\\) 轴走是下坡——鞍点。对比一维 \\(f(x)=-x^2\\)：\\(f&#39;(x)=-2x=0\\) 给 \\(x^*=0\\)，\\(f&#39;&#39;(0)=-2\\lt 0\\) 确认是极大。二阶信息的作用就是分辨这三种驻点。</span></p><p><span class="marginnote">常见误区：初学者容易把「解出 \\(\\nabla f=0\\)」当成问题做完了。实际上驻点未必是最优（鞍点），而且把非负约束晾在一边直接令梯度为零，解出来的可能是负消费——这种解没有经济含义，得交给约束优化的 KKT 框架处理。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不在本课写约束、不引入乘子、不把包络当导数捷径。无穷维变分（欧拉方程）是宏观连续时间的附录，主干的 Ramsey 会在离散时间用贝尔曼，不在这里上变分法。也不把 FONC 读成「市场出清」：梯度零是单人优化，出清是后课均衡。下一课只加等式约束。</p><p>后课默认：内部无约束最优满足 \\(\\nabla f=0\\)；凹最大化时这组方程充分且给出全局最优。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>内点局部最优 \\(\\Rightarrow\\) 梯度为零；二阶半定是必要，定号是局部充分。</li><li>驻点可以是鞍点；凹/凸把驻点升级成全局最优。</li><li>边界点不适用无约束 FONC，交给乘子与 KKT。</li><li>Hessian 非奇异为后课隐函数与比较静态准备矩阵。</li><li>下一课：<a href="/econ/lagrange-multiplier">拉格朗日乘子</a>。</li><li>出处：MWG 数学附录；Boyd and Vandenberghe, <em>Convex Optimization</em>。</li></ul>',8))])}const D=A(d,[["render",f]]);export{b as __pageData,D as default};
